draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50);
  ctx.lineTo(W/2, H/2 - 100 + 50 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 25, H/2 - 75);
  ctx.lineTo(W/2 - 25 + 25 * Math.cos(t), H/2 - 75);
  ctx.lineTo(W/2 - 25, H/2 - 25);
  ctx.closePath();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 25, H/2 - 75);
  ctx.lineTo(W/2 + 25 - 25 * Math.cos(t), H/2 - 75);
  ctx.lineTo(W/2 + 25, H/2 - 25);
  ctx.closePath();
  ctx.stroke();
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('?', W/2, H/2 - 150 + 50 * Math.sin(t));
  ctx.restore();
}
